extra_head_css:
.print-workspace { display: flex; gap: 24px; flex-wrap: wrap; }
    .print-sidebar { flex: 0 0 320px; display: flex; flex-direction: column; gap: 14px; }
    .print-canvas-area { flex: 1; min-width: 300px; }
    @media (max-width: 768px) { .print-workspace { flex-direction: column; } .print-sidebar { flex: none; width: 100%; } }

    .param-row { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
    .param-row label { font-size: .8rem; color: var(--text-secondary); min-width: 110px; font-weight: 500; }
    .param-row select, .param-row input[type="number"] {
      flex: 1; padding: 8px 10px; border: 1px solid var(--border-color); border-radius: 6px;
      background: var(--bg-primary); color: var(--text-primary); font-size: .82rem;
    }

    .preset-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
    .preset-btn {
      padding: 8px 6px; border: 1px solid var(--border-color); border-radius: 8px;
      background: var(--bg-primary); color: var(--text-secondary); cursor: pointer;
      font-size: .72rem; text-align: center; transition: all .2s;
    }
    .preset-btn:hover { border-color: var(--accent); color: var(--text-primary); }
    .preset-btn.active { border-color: var(--accent); background: rgba(99,102,241,.1); color: var(--accent); }

    .preview-wrapper {
      background: repeating-conic-gradient(var(--bg-secondary) 0% 25%, var(--bg-primary) 0% 50%) 50% / 20px 20px;
      border: 1px solid var(--border-color); border-radius: 12px; padding: 16px;
      display: flex; align-items: center; justify-content: center; min-height: 350px; overflow: auto;
    }
    .preview-wrapper canvas { max-width: 100%; max-height: 65vh; border-radius: 4px; box-shadow: 0 4px 20px rgba(0,0,0,.3); }

    .info-row { display: flex; gap: 12px; font-size: .8rem; color: var(--text-secondary); padding: 8px 12px; background: var(--bg-secondary); border-radius: 8px; margin-top: 12px; flex-wrap: wrap; }
    .info-row span { display: flex; align-items: center; gap: 4px; }

    .dimension-display { font-family: 'Fira Code', monospace; font-size: .78rem; color: var(--accent); }
